def ep(kind,metric,a=None,b=None,unit='%',labels=None,result='',hr=None,ci='',interpretation='',status='Peer-reviewed randomised trial',followup='',limitations='',url=''):
 d=dict(endpoint=kind,metric=metric,interpretation=interpretation,analysis_status=status,followup=followup,limitations=limitations,sources=[src('Primary publication',url)])
 if a is not None:d.update(intervention_value=a,comparator_value=b,unit=unit,intervention_label=labels[0],comparator_label=labels[1])
 else:d['result_text']=result
 if hr:d.update(hr=hr,ci=ci)
 return d
